package com.rustyledger;

import com.rustyledger.domain.Account;
import com.rustyledger.domain.Transaction;
import com.rustyledger.service.AccountService;
import com.rustyledger.service.AuditLog;
import com.rustyledger.service.CurrencyConverter;
import com.rustyledger.service.DailyLimitTracker;
import com.rustyledger.service.DailyReportGenerator;
import com.rustyledger.service.FeeCalculator;
import com.rustyledger.service.InstructionHandler;
import com.rustyledger.service.TransactionService;

import java.util.List;

public final class LedgerImpl implements Ledger {

    private final AccountService accountService;
    private final TransactionService transactionService;
    private final FeeCalculator feeCalculator;
    private final CurrencyConverter currencyConverter;
    private final DailyLimitTracker dailyLimitTracker;
    private final AuditLog auditLog;
    private final DailyReportGenerator dailyReportGenerator;
    private final InstructionHandler instructionHandler;

    public LedgerImpl() {
        this.accountService = new AccountService();
        this.transactionService = new TransactionService();
        this.feeCalculator = new FeeCalculator();
        this.currencyConverter = new CurrencyConverter();
        this.dailyLimitTracker = new DailyLimitTracker();
        this.auditLog = new AuditLog();
        this.dailyReportGenerator = new DailyReportGenerator(auditLog, dailyLimitTracker, feeCalculator);
        this.instructionHandler = new InstructionHandler(
                accountService,
                transactionService,
                feeCalculator,
                currencyConverter,
                dailyLimitTracker,
                auditLog,
                dailyReportGenerator
        );
    }

    @Override
    public void openAccount(String id, String tier, String currency, String openingBalance) {
        accountService.openAccount(id, tier, currency, openingBalance);
    }

    @Override
    public String submit(String instruction) {
        return instructionHandler.handle(instruction);
    }

    @Override
    public String balance(String id) {
        Account account = accountService.getAccount(id);
        return account.getBalance() + " " + account.getCurrency();
    }

    @Override
    public List<String> auditLog() {
        return auditLog.getEntries();
    }

    @Override
    public String dailyReport(String date) {
        return dailyReportGenerator.generate(date);
    }
}

