package com.rustyledger.service;

import com.rustyledger.domain.Account;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public final class AccountService {

    private final Map<String, Account> accounts = new HashMap<>();

    public void openAccount(String id, String tier, String currency, String openingBalance) {
        validateAccountId(id);
        validateTier(tier);
        validateCurrency(currency);
        BigDecimal balance = validateAndParseAmount(openingBalance);
        if (accounts.containsKey(id)) {
            throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        }
        accounts.put(id, new Account(id, tier, currency, balance));
    }

    public Account getAccount(String id) {
        Account account = accounts.get(id);
        if (account == null) {
            throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        }
        return account;
    }

    public boolean hasAccount(String id) {
        return accounts.containsKey(id);
    }

    private void validateAccountId(String id) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) {
            throw new IllegalArgumentException("INVALID ACCOUNT ID");
        }
    }

    private void validateTier(String tier) {
        if (!"STANDARD".equals(tier) && !"PREMIUM".equals(tier) && !"STAFF".equals(tier)) {
            throw new IllegalArgumentException("INVALID TIER: " + tier);
        }
    }

    private void validateCurrency(String currency) {
        if (!"PLN".equals(currency) && !"EUR".equals(currency) && !"USD".equals(currency)) {
            throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        }
    }

    private BigDecimal validateAndParseAmount(String amountText) {
        if (amountText == null || !amountText.matches("\\d+(\\.\\d{1,2})?")) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amountText);
        }
        return new BigDecimal(amountText).setScale(2);
    }
}

