package com.rustyledger.service;

import com.rustyledger.domain.Account;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class FeeCalculator {

    private static final BigDecimal STANDARD_RATE = new BigDecimal("0.005");
    private static final BigDecimal STANDARD_MIN = new BigDecimal("0.20");
    private static final BigDecimal PREMIUM_RATE = new BigDecimal("0.0025");
    private static final BigDecimal PREMIUM_MIN = new BigDecimal("0.10");
    private static final BigDecimal PREMIUM_MAX = new BigDecimal("5.00");
    private static final BigDecimal WITHDRAW_STANDARD_FEE = new BigDecimal("1.00");
    private static final BigDecimal ZERO = new BigDecimal("0.00");

    public BigDecimal calculateTransferFee(Account fromAccount, BigDecimal amount) {
        String tier = fromAccount.getTier();
        if ("STANDARD".equals(tier)) {
            return calculateStandardFee(amount);
        } else if ("PREMIUM".equals(tier)) {
            return calculatePremiumFee(amount);
        }
        return ZERO;
    }

    public BigDecimal calculateWithdrawalFee(Account account) {
        return account.isStandard() ? WITHDRAW_STANDARD_FEE : ZERO;
    }

    public BigDecimal calculateDepositFee() {
        return ZERO;
    }

    private BigDecimal calculateStandardFee(BigDecimal amount) {
        BigDecimal fee = amount.multiply(STANDARD_RATE).setScale(2, RoundingMode.HALF_UP);
        return fee.max(STANDARD_MIN);
    }

    private BigDecimal calculatePremiumFee(BigDecimal amount) {
        BigDecimal fee = amount.multiply(PREMIUM_RATE).setScale(2, RoundingMode.HALF_UP);
        return fee.max(PREMIUM_MIN).min(PREMIUM_MAX);
    }
}

package com.rustyledger.service;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class CurrencyConverter {

    private static final BigDecimal EUR_RATE = new BigDecimal("4.30");
    private static final BigDecimal USD_RATE = new BigDecimal("4.00");
    private static final BigDecimal PLN_RATE = new BigDecimal("1.00");
    private static final BigDecimal SPREAD = new BigDecimal("0.985");
    private static final BigDecimal FOUR_DECIMALS = new BigDecimal("0.0001");

    public BigDecimal convert(BigDecimal amount, String fromCurrency, String toCurrency, String tier) {
        if (fromCurrency.equals(toCurrency)) {
            return amount;
        }
        BigDecimal inPln = amount.multiply(rate(fromCurrency)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(toCurrency), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) {
            result = result.multiply(SPREAD);
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }

    private BigDecimal rate(String currency) {
        return switch (currency) {
            case "EUR" -> EUR_RATE;
            case "USD" -> USD_RATE;
            default -> PLN_RATE;
        };
    }
}

package com.rustyledger.service;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public final class DailyLimitTracker {

    private static final BigDecimal STANDARD_LIMIT = new BigDecimal("5000.00");
    private static final BigDecimal PREMIUM_LIMIT = new BigDecimal("20000.00");
    private static final BigDecimal STAFF_LIMIT = new BigDecimal("50000.00");
    private static final BigDecimal PREMIUM_OVERDRAFT = new BigDecimal("500.00");

    private final Map<String, BigDecimal> usedAmounts = new HashMap<>();

    public BigDecimal getUsedToday(String accountId, String date) {
        return usedAmounts.getOrDefault(accountId + "|" + date, BigDecimal.ZERO);
    }

    public void addUsage(String accountId, String date, BigDecimal amount) {
        String key = accountId + "|" + date;
        BigDecimal current = usedAmounts.getOrDefault(key, BigDecimal.ZERO);
        usedAmounts.put(key, current.add(amount));
    }

    public BigDecimal getLimit(String tier) {
        return switch (tier) {
            case "STANDARD" -> STANDARD_LIMIT;
            case "PREMIUM" -> PREMIUM_LIMIT;
            default -> STAFF_LIMIT;
        };
    }

    public BigDecimal getOverdraft(String tier) {
        return "PREMIUM".equals(tier) ? PREMIUM_OVERDRAFT : BigDecimal.ZERO;
    }

    public boolean wouldExceedLimit(String accountId, String date, BigDecimal amount, String tier) {
        BigDecimal used = getUsedToday(accountId, date);
        BigDecimal limit = getLimit(tier);
        return used.add(amount).compareTo(limit) > 0;
    }
}

