package com.rustyledger.service;

import com.rustyledger.domain.Transaction;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public final class DailyReportGenerator {

    private final AuditLog auditLog;
    private final DailyLimitTracker dailyLimitTracker;
    private final FeeCalculator feeCalculator;

    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();

    public DailyReportGenerator(AuditLog auditLog, DailyLimitTracker dailyLimitTracker,
            FeeCalculator feeCalculator) {
        this.auditLog = auditLog;
        this.dailyLimitTracker = dailyLimitTracker;
        this.feeCalculator = feeCalculator;
    }

    public void recordOk(String date) {
        incrementCount(date, 0);
    }

    public void recordRejected(String date) {
        incrementCount(date, 1);
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) {
            return;
        }
        Map<String, BigDecimal> map = fees.computeIfAbsent(date, k -> new TreeMap<>());
        BigDecimal old = map.get(currency);
        map.put(currency, old == null ? delta : old.add(delta));
    }

    public String generate(String date) {
        int[] c = counts.get(date);
        int ok = c == null ? 0 : c[0];
        int rejected = c == null ? 0 : c[1];
        Map<String, BigDecimal> f = fees.get(date);
        String feeText = "none";
        if (f != null && !f.isEmpty()) {
            StringBuilder sb = new StringBuilder();
            for (Map.Entry<String, BigDecimal> e : f.entrySet()) {
                if (sb.length() > 0) {
                    sb.append(", ");
                }
                sb.append(e.getValue()).append(" ").append(e.getKey());
            }
            feeText = sb.toString();
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }

    private void incrementCount(String date, int slot) {
        int[] c = counts.get(date);
        if (c == null) {
            c = new int[2];
            counts.put(date, c);
        }
        c[slot]++;
    }
}

package com.rustyledger.service;

import com.rustyledger.domain.Account;
import com.rustyledger.domain.Transaction;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class InstructionHandler {

    private final AccountService accountService;
    private final TransactionService transactionService;
    private final FeeCalculator feeCalculator;
    private final CurrencyConverter currencyConverter;
    private final DailyLimitTracker dailyLimitTracker;
    private final AuditLog auditLog;
    private final DailyReportGenerator dailyReportGenerator;

    public InstructionHandler(AccountService accountService,
            TransactionService transactionService,
            FeeCalculator feeCalculator,
            CurrencyConverter currencyConverter,
            DailyLimitTracker dailyLimitTracker,
            AuditLog auditLog,
            DailyReportGenerator dailyReportGenerator) {
        this.accountService = accountService;
        this.transactionService = transactionService;
        this.feeCalculator = feeCalculator;
        this.currencyConverter = currencyConverter;
        this.dailyLimitTracker = dailyLimitTracker;
        this.auditLog = auditLog;
        this.dailyReportGenerator = dailyReportGenerator;
    }

    public String handle(String line) {
        if (line == null || line.trim().isEmpty()) {
            return reject("???", null, "BAD_INSTRUCTION", "empty instruction");
        }
        String[] parts = line.split("\\|", -1);
        String verb = parts[0];
        int expectedFields = expectedFields(verb);
        if (expectedFields < 0) {
            return reject("???", null, "BAD_INSTRUCTION", "unknown verb " + verb);
        }
        if (parts.length != expectedFields) {
            return reject(verb, null, "BAD_INSTRUCTION", verb + " needs " + expectedFields + " fields");
        }
        String date = parts[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) {
            return reject(verb, null, "BAD_DATE", date);
        }
        if ("REVERSE".equals(verb)) {
            return handleReverse(date, parts[2]);
        }
        String amountText = "TRANSFER".equals(verb) ? parts[4] : parts[3];
        BigDecimal amount = parseAmount(amountText);
        if (amount == null) {
            return reject(verb, date, "BAD_AMOUNT", amountText);
        }
        return switch (verb) {
            case "TRANSFER" -> handleTransfer(date, parts[2], parts[3], amount, parts[5]);
            case "WITHDRAW" -> handleWithdraw(date, parts[2], amount);
            case "DEPOSIT" -> handleDeposit(date, parts[2], amount);
            default -> reject(verb, date, "BAD_INSTRUCTION", "unknown verb " + verb);
        };
    }

    private int expectedFields(String verb) {
        return switch (verb) {
            case "TRANSFER" -> 6;
            case "WITHDRAW", "DEPOSIT" -> 4;
            case "REVERSE" -> 3;
            default -> -1;
        };
    }

    private BigDecimal parseAmount(String text) {
        if (!text.matches("\\d+(\\.\\d{1,2})?")) {
            return null;
        }
        BigDecimal amount = new BigDecimal(text).setScale(2);
        return amount.signum() > 0 ? amount : null;
    }

    private String handleTransfer(String date, String fromId, String toId,
            BigDecimal amount, String currency) {
        Account from = accountService.getAccountOrNull(fromId);
        if (from == null) {
            return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", fromId);
        }
        Account to = accountService.getAccountOrNull(toId);
        if (to == null) {
            return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", toId);
        }
        if (fromId.equals(toId)) {
            return reject("TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        }
        if (!from.getCurrency().equals(currency)) {
            return reject("TRANSFER", date, "CURRENCY_MISMATCH", fromId + " holds " + from.getCurrency());
        }
        BigDecimal fee = feeCalculator.calculateTransferFee(from, amount);
        String rejection = checkLimitAndFunds(date, from, amount, fee);
        if (rejection != null) {
            return reject("TRANSFER", date, rejection.code(), rejection.message());
        }
        BigDecimal credited = currencyConverter.convert(amount, from.getCurrency(),
                to.getCurrency(), from.getTier());
        from.subtractFromBalance(amount.add(fee));
        to.addToBalance(credited);
        dailyLimitTracker.addUsage(fromId, date, amount);
        String txId = transactionService.nextTransactionId();
        Transaction tx = new Transaction(txId, "TRANSFER", date, fromId, toId,
                amount, from.getCurrency(), fee, credited);
        transactionService.addTransaction(tx);
        dailyReportGenerator.addFee(date, from.getCurrency(), fee);
        return accept("TRANSFER", date, txId, "fee=" + fee + " " + from.getCurrency());
    }

    private String handleWithdraw(String date, String id, BigDecimal amount) {
        Account account = accountService.getAccountOrNull(id);
        if (account == null) {
            return reject("WITHDRAW", date, "UNKNOWN_ACCOUNT", id);
        }
        BigDecimal fee = feeCalculator.calculateWithdrawalFee(account);
        String rejection = checkLimitAndFunds(date, account, amount, fee);
        if (rejection != null) {
            return reject("WITHDRAW", date, rejection.code(), rejection.message());
        }
        account.subtractFromBalance(amount.add(fee));
        dailyLimitTracker.addUsage(id, date, amount);
        String txId = transactionService.nextTransactionId();
        Transaction tx = new Transaction(txId, "WITHDRAW", date, id, "",
                amount, account.getCurrency(), fee, amount);
        transactionService.addTransaction(tx);
        dailyReportGenerator.addFee(date, account.getCurrency(), fee);
        return accept("WITHDRAW", date, txId, "fee=" + fee + " " + account.getCurrency());
    }

    private String handleDeposit(String date, String id, BigDecimal amount) {
        Account account = accountService.getAccountOrNull(id);
        if (account == null) {
            return reject("DEPOSIT", date, "UNKNOWN_ACCOUNT", id);
        }
        account.addToBalance(amount);
        String txId = transactionService.nextTransactionId();
        Transaction tx = new Transaction(txId, "DEPOSIT", date, id, "",
                amount, account.getCurrency(), BigDecimal.ZERO, amount);
        transactionService.addTransaction(tx);
        return accept("DEPOSIT", date, txId, "fee=0.00 " + account.getCurrency());
    }

    private String handleReverse(String date, String txId) {
        Transaction tx = transactionService.getTransaction(txId);
        if (tx == null) {
            return reject("REVERSE", date, "UNKNOWN_TX", txId);
        }
        if (!tx.isTransfer()) {
            return reject("REVERSE", date, "NOT_REVERSIBLE", txId + " is a " + tx.getType());
        }
        if (tx.isReversed()) {
            return reject("REVERSE", date, "ALREADY_REVERSED", txId);
        }
        if (!tx.getDate().equals(date)) {
            return reject("REVERSE", date, "REVERSAL_WINDOW", txId + " was made on " + tx.getDate());
        }
        Account from = accountService.getAccountOrNull(tx.getFromAccount());
        Account to = accountService.getAccountOrNull(tx.getToAccount());
        BigDecimal fee = tx.getFee();
        to.subtractFromBalance(tx.getCreditedAmount());
        BigDecimal back = tx.getAmount();
        if (from != null && from.isPremium()) {
            back = back.add(fee);
            if (fee.signum() != 0) {
                dailyReportGenerator.addFee(date, from.getCurrency(), fee.negate());
            }
        }
        if (from != null) {
            from.addToBalance(back);
        }
        tx.markReversed();
        String newTxId = transactionService.nextTransactionId();
        Transaction reverseTx = new Transaction(newTxId, "REVERSE", date,
                tx.getFromAccount(), tx.getToAccount(), tx.getAmount(),
                tx.getCurrency(), BigDecimal.ZERO, tx.getCreditedAmount());
        reverseTx.markReversed();
        transactionService.addTransaction(reverseTx);
        return accept("REVERSE", date, newTxId, "reversed " + txId);
    }

    private record Rejection(String code, String message) {}

    private Rejection checkLimitAndFunds(String date, Account account,
            BigDecimal amount, BigDecimal fee) {
        String tier = account.getTier();
        if (dailyLimitTracker.wouldExceedLimit(account.getId(), date, amount, tier)) {
            BigDecimal limit = dailyLimitTracker.getLimit(tier);
            return new Rejection("LIMIT_EXCEEDED",
                    "daily limit " + limit + " for " + tier);
        }
        BigDecimal balance = account.getBalance();
        BigDecimal needed = amount.add(fee);
        BigDecimal overdraft = dailyLimitTracker.getOverdraft(tier);
        if (balance.subtract(needed).compareTo(overdraft.negate()) < 0) {
            return new Rejection("INSUFFICIENT_FUNDS",
                    "balance " + balance + " " + account.getCurrency() + ", needed " + needed + " " + account.getCurrency());
        }
        return null;
    }

    private String accept(String verb, String date, String txId, String extra) {
        dailyReportGenerator.recordOk(date);
        auditLog.record(verb, date, "OK " + txId);
        return "OK " + txId + " " + extra;
    }

    private String reject(String verb, String date, String code, String message) {
        if (date != null) {
            dailyReportGenerator.recordRejected(date);
        }
        String auditDate = date != null ? date : "????-??-??";
        auditLog.record(verb, auditDate, "REJECTED " + code);
        return "REJECTED " + code + ": " + message;
    }
}

