import java.math.BigDecimal;

public final class ReverseHandler {

    private final AccountService accountService;
    private final TransactionService transactionService;
    private final DailyReportGenerator dailyReportGenerator;
    private final AuditLog auditLog;

    public ReverseHandler(AccountService accountService,
            TransactionService transactionService,
            DailyReportGenerator dailyReportGenerator,
            AuditLog auditLog) {
        this.accountService = accountService;
        this.transactionService = transactionService;
        this.dailyReportGenerator = dailyReportGenerator;
        this.auditLog = auditLog;
    }

    public String handle(String date, String txId) {
        Transaction tx = transactionService.getTransaction(txId);
        if (tx == null) {
            return reject("REVERSE", date, "UNKNOWN_TX", txId);
        }
        if (!tx.isTransfer()) {
            return reject("REVERSE", date, "NOT_REVERSIBLE", txId + " is a " + tx.getType());
        }
        if (tx.isReversed()) {
            return reject("REVERSE", date, "ALREADY_REVERSED", txId);
        }
        if (!tx.getDate().equals(date)) {
            return reject("REVERSE", date, "REVERSAL_WINDOW", txId + " was made on " + tx.getDate());
        }
        Account from = accountService.getAccountOrNull(tx.getFromAccount());
        Account to = accountService.getAccountOrNull(tx.getToAccount());
        BigDecimal fee = tx.getFee();
        to.subtractFromBalance(tx.getCreditedAmount());
        BigDecimal back = tx.getAmount();
        if (from != null && from.isPremium()) {
            back = back.add(fee);
            if (fee.signum() != 0) {
                dailyReportGenerator.addFee(date, from.getCurrency(), fee.negate());
            }
        }
        if (from != null) {
            from.addToBalance(back);
        }
        tx.markReversed();
        String newTxId = transactionService.nextTransactionId();
        Transaction reverseTx = new Transaction(newTxId, "REVERSE", date,
                tx.getFromAccount(), tx.getToAccount(), tx.getAmount(),
                tx.getCurrency(), BigDecimal.ZERO, tx.getCreditedAmount());
        reverseTx.markReversed();
        transactionService.addTransaction(reverseTx);
        return accept("REVERSE", date, newTxId, "reversed " + txId);
    }

