package com.rustyledger.service;

import com.rustyledger.domain.Account;
import com.rustyledger.domain.Transaction;

import java.math.BigDecimal;

public final class TransferHandler {

    private final AccountService accountService;
    private final TransactionService transactionService;
    private final FeeCalculator feeCalculator;
    private final CurrencyConverter currencyConverter;
    private final DailyLimitTracker dailyLimitTracker;
    private final DailyReportGenerator dailyReportGenerator;
    private final AuditLog auditLog;

    public TransferHandler(AccountService accountService,
            TransactionService transactionService,
            FeeCalculator feeCalculator,
            CurrencyConverter currencyConverter,
            DailyLimitTracker dailyLimitTracker,
            DailyReportGenerator dailyReportGenerator,
            AuditLog auditLog) {
        this.accountService = accountService;
        this.transactionService = transactionService;
        this.feeCalculator = feeCalculator;
        this.currencyConverter = currencyConverter;
        this.dailyLimitTracker = dailyLimitTracker;
        this.dailyReportGenerator = dailyReportGenerator;
        this.auditLog = auditLog;
    }

    public String handle(String date, String fromId, String toId,
            BigDecimal amount, String currency) {
        Account from = accountService.getAccountOrNull(fromId);
        if (from == null) {
            return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", fromId);
        }
        Account to = accountService.getAccountOrNull(toId);
        if (to == null) {
            return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", toId);
        }
        String basicValidation = validateBasicRules(fromId, from, to, currency, date);
        if (basicValidation != null) {
            return basicValidation;
        }
        BigDecimal fee = feeCalculator.calculateTransferFee(from, amount);
        Rejection limitCheck = checkLimitAndFunds(date, from, amount, fee);
        if (limitCheck != null) {
            return reject("TRANSFER", date, limitCheck.code(), limitCheck.message());
        }
        executeTransfer(from, to, date, fromId, toId, amount, fee, currency);
        return recordTransfer(date, from, fee);
    }

    private String validateBasicRules(String fromId, Account from, Account to,
            String currency, String date) {
        if (fromId.equals(to.getId())) {
            return reject("TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        }
        if (!from.getCurrency().equals(currency)) {
            return reject("TRANSFER", date, "CURRENCY_MISMATCH", fromId + " holds " + from.getCurrency());
        }
        return null;
    }

    private void executeTransfer(Account from, Account to, String date,
            String fromId, String toId, BigDecimal amount, BigDecimal fee, String currency) {
        BigDecimal credited = currencyConverter.convert(amount, from.getCurrency(),
                to.getCurrency(), from.getTier());
        from.subtractFromBalance(amount.add(fee));
        to.addToBalance(credited);
        dailyLimitTracker.addUsage(fromId, date, amount);
        String txId = transactionService.nextTransactionId();
        Transaction tx = new Transaction(txId, "TRANSFER", date, fromId, toId,
                amount, from.getCurrency(), fee, credited);
        transactionService.addTransaction(tx);
        dailyReportGenerator.addFee(date, from.getCurrency(), fee);
    }

    private Rejection checkLimitAndFunds(String date, Account account,
            BigDecimal amount, BigDecimal fee) {
        String tier = account.getTier();
        if (dailyLimitTracker.wouldExceedLimit(account.getId(), date, amount, tier)) {
            BigDecimal limit = dailyLimitTracker.getLimit(tier);
            return new Rejection("LIMIT_EXCEEDED",
                    "daily limit " + limit + " for " + tier);
        }
        BigDecimal balance = account.getBalance();
        BigDecimal needed = amount.add(fee);
        BigDecimal overdraft = dailyLimitTracker.getOverdraft(tier);
        if (balance.subtract(needed).compareTo(overdraft.negate()) < 0) {
            return new Rejection("INSUFFICIENT_FUNDS",
                    "balance " + balance + " " + account.getCurrency() + ", needed " + needed + " " + account.getCurrency());
        }
        return null;
    }

    private String recordTransfer(String date, Account from, BigDecimal fee) {
        return accept("TRANSFER", date, "TX-" + transactionService.nextTransactionId(), "fee=" + fee + " " + from.getCurrency());
    }

    private String accept(String verb, String date, String txId, String extra) {
        dailyReportGenerator.recordOk(date);
        auditLog.record(verb, date, "OK " + txId);
        return "OK " + txId + " " + extra;
    }

    private String reject(String verb, String date, String code, String message) {
        dailyReportGenerator.recordRejected(date);
        auditLog.record(verb, date, "REJECTED " + code);
        return "REJECTED " + code + ": " + message;
    }

    private record Rejection(String code, String message) {}
}
